import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"漸","description":"焦氏易林注 - 漸","frontmatter":{"title":"漸","description":"焦氏易林注 - 漸"},"headers":[],"relativePath":"classics/jiaoyilin/053.md","filePath":"classics/jiaoyilin/053.md"}'),l={name:"classics/jiaoyilin/053.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><h3 id="漸-1" tabindex="-1">漸 <a class="header-anchor" href="#漸-1" aria-label="Permalink to “漸”">​</a></h3><h3 id="漸之乾" tabindex="-1">漸之乾 <a class="header-anchor" href="#漸之乾" aria-label="Permalink to “漸之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>旦種谷豆，暮成藿羹。心之所願，志快意愜。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳前。以其為乾卦，故再釋之，此用漸象。伏震為旦，巽為谷豆、為藜藿，坎為暮、為羹。旦種暮食，言其速也。坎為心志，兌悅，故曰快、曰愜。○谷，宋元本作菽，菽，亦豆也，故從汲古。</p><h3 id="漸之坤" tabindex="-1">漸之坤 <a class="header-anchor" href="#漸之坤" aria-label="Permalink to “漸之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>牡飛門啟，憂患大解，不為身禍。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坎為牡，艮為門，漸變，坤中虛，故曰牡飛門啟。坎為憂患，變坤，故曰憂患大解。坤為身、為禍，風散，故不為身禍。</p><h3 id="漸之屯" tabindex="-1">漸之屯 <a class="header-anchor" href="#漸之屯" aria-label="Permalink to “漸之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>東山西山，各自止安。雖相登望，竟未同堂。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《坤》。艮山，震東，坎西，艮為止、為望、為堂，震為登。</p><h3 id="漸之蒙" tabindex="-1">漸之蒙 <a class="header-anchor" href="#漸之蒙" aria-label="Permalink to “漸之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>眾鳥所翔，中有大怪。九身無頭，魂驚魄去，不可以居。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《同人》。丁雲：郭璞《江賦》奇鶬九頭，《御覽》：《典略》雲：齊園有九頭鳥，赤色，似鴨，九頭皆鳴，又引《嶺表錄異》雲：鬼車入人家煉人魂氣。又《酉陽雜俎》亦雲鬼車十首，後為犬爵落一首。</p><h3 id="漸之需" tabindex="-1">漸之需 <a class="header-anchor" href="#漸之需" aria-label="Permalink to “漸之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>交侵如亂，民無聊賴。追戎濟西，敵人破陣。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。坤為亂、為民，坤喪，故民無聊賴。坤為戎，坎為西，坎水，故曰濟西。坎為破，坤為師，故曰破陣。《左傳莊十八年》追戎於濟西，不言其來，諱之也。○戎，汲古訛我，敵人破陣作狄人便殫，均依宋元本。</p><h3 id="漸之訟" tabindex="-1">漸之訟 <a class="header-anchor" href="#漸之訟" aria-label="Permalink to “漸之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>麟鳳所翔，國無咎殃。賈市十倍，復歸惠鄉。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>互離為文，故曰麟鳳。伏坤為國，巽為賈市、為倍，坤數十，故曰賈市十倍。坤為鄉，震為歸、為惠。</p><h3 id="漸之師" tabindex="-1">漸之師 <a class="header-anchor" href="#漸之師" aria-label="Permalink to “漸之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>鑿井求玉，非卞氏寶。身困名辱，勞無所得。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>互震為寶玉，坎為井、為困辱、為勞，坤為身，艮為名，二四艮覆，故曰名辱。○寶。宋元本作室。汲古作宅，依局本。</p><h3 id="漸之比" tabindex="-1">漸之比 <a class="header-anchor" href="#漸之比" aria-label="Permalink to “漸之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>文山鴻豹，肥腯多脂。王孫獲願，載福巍巍。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>陸佃《埤雅》引郭璞曰鴻似雁，無後趾，毛有釣文，亦名鴻豹。易林文山鴻豹謂此也。坤為文，艮為山、為鴻、為豹，故曰文山鴻豹。伏乾為肥，坎為膏、為脂，艮為孫，伏乾，故曰王孫。艮山形長，故曰巍巍。</p><h3 id="漸之小畜" tabindex="-1">漸之小畜 <a class="header-anchor" href="#漸之小畜" aria-label="Permalink to “漸之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>周成之隆，刑措除兇。太宰費石，君子作人。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為周，艮為成，坎為刑法，坤為兇，艮止，故曰刑措除兇。艮為官、為石，故曰太宰費石。按：《左傳莊八年》反誅屨於徒人費，鞭之見血出，遇賊於門，袒而示之臂，請先入，伏公而出，鬬死於門中，石之紛如死於階下。費石皆忠於襄公者，故下曰作人。艮為君子。○石，汲古作佑，依宋元本。</p><h3 id="漸之履" tabindex="-1">漸之履 <a class="header-anchor" href="#漸之履" aria-label="Permalink to “漸之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>圭璧琮璋，執贄見王。百裡寧戚，應聘齊秦。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《井》。○璋，宋元本作璜。</p><h3 id="漸之泰" tabindex="-1">漸之泰 <a class="header-anchor" href="#漸之泰" aria-label="Permalink to “漸之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>穿空漏徹，破壞殘缺。陶弗能冶，瓦甓不鑿。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伏巽為空漏，兌為破缺，伏艮為火，故曰陶冶破缺，故不能陶冶。艮為瓦甓，坤虛，故不必鑿。</p><h3 id="漸之否" tabindex="-1">漸之否 <a class="header-anchor" href="#漸之否" aria-label="Permalink to “漸之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>鴻飛遵陸，公出不復，伯氏客宿。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《蹇》。</p><h3 id="漸之同人" tabindex="-1">漸之同人 <a class="header-anchor" href="#漸之同人" aria-label="Permalink to “漸之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>蝦蟇群聚，從天請雨，雲雷運集，應其願所。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《升》。末句汲古作&quot;應時輙下，得其所願&quot;，依宋元本。又運汲古作連，亦非。</p><h3 id="漸之大有" tabindex="-1">漸之大有 <a class="header-anchor" href="#漸之大有" aria-label="Permalink to “漸之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>老弱無子，不能自理。為民所憂，終不離咎。管子治國，侯伯賓服。乘輿八百，尊我桓德。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為老弱，三至五震覆，故曰無子。坤為民、為咎，坎為憂，艮為終。離，同罹。後四句與上文意不屬，定為崔篆虞翻等林辭所竄人者。○桓，元本訛恆，依宋本、汲古。</p><h3 id="漸之謙" tabindex="-1">漸之謙 <a class="header-anchor" href="#漸之謙" aria-label="Permalink to “漸之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>播梅折枝，與母別離，絕不相知。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《謙》。播，種也，言折枝種於他處。與母別離者，言此枝與母樹分離也。震為梅、為枝、為耕種，坤為母，丁宴釋文引《說苑》執一枝梅事為解，皆由播訛為蟠之誤也。○播，各本皆作蟠，依《訟》之《謙》校。</p><h3 id="漸之豫" tabindex="-1">漸之豫 <a class="header-anchor" href="#漸之豫" aria-label="Permalink to “漸之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>盛中不絕，衰老復拙。盈滿減虧，瘯腯肥。鄭昭失國，重耳興起。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為盛，坎為中，坤為老、為減虧，艮為節，故曰瘯、曰肥腯。坎為鄭，艮為光明，故曰鄭昭。坎為失，坤為國，故曰失國。坎為耳，坤為重，震起，故曰重耳興起。○瘯，元本作痴，依宋本、汲古。《左傳桓六年》謂其不疾瘯蠡也。註：瘯蠡，疥癬，蠡不從病即瘰字。</p><h3 id="漸之隨" tabindex="-1">漸之隨 <a class="header-anchor" href="#漸之隨" aria-label="Permalink to “漸之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>聞虎入邑，必欲逃匿。走據陽德，不見霍叔，終無憂慝。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為邑、為虎，巽為入，兌為聞，故曰聞虎入邑。《戰國策》夫市無虎明矣，然而三人言而成市虎。巽為隱伏，故曰逃匿。震為走，艮納丙為山陽，故曰走據陽德。艮為叔、為山，故曰霍叔。巽伏，故不見。艮為終，丁宴所釋至為牽強，不可從，闕疑可也。○心，宋元本作必，走作無，陽作易，均依汲古。霍叔，元本作藿菽，依宋元本、汲古。終，汲古作絕，依宋元本。易林以兌為耳，故為聞。</p><h3 id="漸之蠱" tabindex="-1">漸之蠱 <a class="header-anchor" href="#漸之蠱" aria-label="Permalink to “漸之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>隨時逐便，不失利門。多獲得福，富於封君。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為時，震為逐，巽為利，艮為門，故曰利門。震為福、為君。</p><h3 id="漸之臨" tabindex="-1">漸之臨 <a class="header-anchor" href="#漸之臨" aria-label="Permalink to “漸之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>禹作神鼎，伯益銜指。斧斤既折，憧立獨坐。賈市不讎，枯槁為禍。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《益》。憧，宋元本作撞，依汲古。坐，各本皆作倚，依《小畜》之《益》校。市，宋元本作萬，依汲古。讎，宋本、汲古皆作售，依元本。</p><h3 id="漸之觀" tabindex="-1">漸之觀 <a class="header-anchor" href="#漸之觀" aria-label="Permalink to “漸之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>春鴻飛東，以馬貨金。利得十倍，重載歸鄉。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《中孚》。</p><h3 id="漸之噬嗑" tabindex="-1">漸之噬嗑 <a class="header-anchor" href="#漸之噬嗑" aria-label="Permalink to “漸之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>金齒鐵牙，壽考宜家。年歲有餘，貪利者得。雖憂無咎。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為金鐵、為壽考，伏兌為齒牙，震為年歲、為有餘。伏巽為利，坎為憂，震解，故無咎也。○餘，宋元本作儲，依汲古。</p><h3 id="漸之賁" tabindex="-1">漸之賁 <a class="header-anchor" href="#漸之賁" aria-label="Permalink to “漸之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>膏澤沐浴，洗去汙辱。振除災咎，更與福處。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>互坎故曰膏沐、曰洗去汙辱。離為災，震為福。</p><h3 id="漸之剝" tabindex="-1">漸之剝 <a class="header-anchor" href="#漸之剝" aria-label="Permalink to “漸之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>履階登墀，高升峻巍。福祿洋溢，依天之威。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤形似階墀，而一陽在上，故曰履階登墀，高升峻巍。伏乾為福祿、為天，坤水，故曰洋溢。○升，宋元本作登，依汲古。</p><h3 id="漸之復" tabindex="-1">漸之復 <a class="header-anchor" href="#漸之復" aria-label="Permalink to “漸之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>坤厚地德，庶物蕃息。平康正直，以綏大福。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>坤為庶物，震為生，故曰蕃息。坤為平、為直，震為福。</p><h3 id="漸之無妄" tabindex="-1">漸之無妄 <a class="header-anchor" href="#漸之無妄" aria-label="Permalink to “漸之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>絕域異路，多所畏避。使我驚惶，思吾故處。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>伏升。坤為域，兌決，故曰絕域。震為大塗，巽為歧，故曰異路。巽伏，乾惕，故曰畏避。坤為我，震為驚。○惶，宋元本作懼，依汲古。</p><h3 id="漸之大畜" tabindex="-1">漸之大畜 <a class="header-anchor" href="#漸之大畜" aria-label="Permalink to “漸之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>襁褓孩幼，冠帶成家。出門如賓，父母何憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《恆》。茲取象旁通萃。</p><h3 id="漸之頤" tabindex="-1">漸之頤 <a class="header-anchor" href="#漸之頤" aria-label="Permalink to “漸之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>一尋百節，綢繆相結。其指詰屈，不能解脫。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>八尺曰尋，坤卦數八，故曰一尋。艮多節，坤為百，故曰一尋百節。伏巽為結，艮為指，震為解脫，下卦艮反，故曰其指詰屈。○屈，元本作詘，依汲古。</p><h3 id="漸之大過" tabindex="-1">漸之大過 <a class="header-anchor" href="#漸之大過" aria-label="Permalink to “漸之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>鷹鸇獵食，雉兔困極。逃頭見尾，為人所賊。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。艮為鷹鸇，震為食，坤文為雉，震為兔，正反艮故曰困極。艮為頭，在上，故曰逃。而下為覆艮，艮為尾，故曰見尾。本卦兌為見，巽為賊，震為人，坤殺，故曰為人所賊。賊，害也。○人，宋元本作害，非，依汲古。</p><h3 id="漸之坎" tabindex="-1">漸之坎 <a class="header-anchor" href="#漸之坎" aria-label="Permalink to “漸之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>危坐至暮，請求不得。膏澤不降，政戾民忒。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>忒，宋元本、汲古作惑，依局本。民，汲古作弗，非，依宋元本。艮為坐、為請求，坎為暮，坎失，故不得。坎為膏澤，艮止，故不降。坤為政、為民，坎折坤，故政戾民忒。</p><h3 id="漸之離" tabindex="-1">漸之離 <a class="header-anchor" href="#漸之離" aria-label="Permalink to “漸之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>剛柔相呼，二姓為家。霜降既同，惠我以仁。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《損》。</p><h3 id="漸之鹹" tabindex="-1">漸之鹹 <a class="header-anchor" href="#漸之鹹" aria-label="Permalink to “漸之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>慈母念子，饗賜得士。蠻夷來服，國人歡喜。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>伏損。坤為慈，母為思念，震為子、為士。兌時，故曰饗。坤為夷狄、為國，震為人、為喜。</p><h3 id="漸之恆" tabindex="-1">漸之恆 <a class="header-anchor" href="#漸之恆" aria-label="Permalink to “漸之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>良夫孔姬，脅悝登臺。柴季不扶，衛輒走逃。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《恆》。</p><h3 id="漸之遯" tabindex="-1">漸之遯 <a class="header-anchor" href="#漸之遯" aria-label="Permalink to “漸之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>子長忠直，李陵為賊。禍及無嗣，司馬失福。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>互巽為長、為直、為桃李，艮山，故曰李陵。巽為賊，巽下斷，故曰無嗣。乾為馬、為福，陰消陽，故曰司馬失福，謂司馬子長因救李陵，而被腐刑也。○李陵，宋本作李氏，汲古作季氏，依元本。</p><h3 id="漸之大壯" tabindex="-1">漸之大壯 <a class="header-anchor" href="#漸之大壯" aria-label="Permalink to “漸之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>節度之德，不涉亂國。雖昧無光，後大受慶。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏艮為節。坤為亂、為國，坤伏，故曰不涉亂國。坤為黑，故曰昧、曰無光。震為後，乾為大。</p><h3 id="漸之晉" tabindex="-1">漸之晉 <a class="header-anchor" href="#漸之晉" aria-label="Permalink to “漸之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>驅羊南行，與禍相逢。狼驚我馬，虎盜我子，悲恨自咎。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>伏兌為羊，離為南，中爻坎，故曰與禍相逢。艮為虎狼，坎為馬、為盜，震為子，二至四震覆，故子為虎盜。坎為悲恨。</p><h3 id="漸之明夷" tabindex="-1">漸之明夷 <a class="header-anchor" href="#漸之明夷" aria-label="Permalink to “漸之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>尼父孔丘，善釣鯉魚。羅網一舉，獲利萬頭，富我家居。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>網，宋元作鉤，依汲古。○震為陵、為父、為孔、為丘，故曰尼父孔丘。坤為魚，離為羅網，坤為利、為萬，坎為首，故曰獲利萬頭。坎為室家，坤為富。</p><h3 id="漸之家人" tabindex="-1">漸之家人 <a class="header-anchor" href="#漸之家人" aria-label="Permalink to “漸之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>本根不固，華葉落去，更為孤嫗。本，宋元本訛大。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>○巽為枯，下斷，故曰本根不固。伏震為華葉，巽隕落，故曰華葉落去。巽為寡、為婦，故曰孤嫗。</p><h3 id="漸之睽" tabindex="-1">漸之睽 <a class="header-anchor" href="#漸之睽" aria-label="Permalink to “漸之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>設罟捕魚，反得屠諸。員困竭忠，伍氏夷誅。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《漸》象。互離為罔罟，巽為魚，艮手為捕，故曰設罟捕魚。坎為匕、為刺，故曰屠諸，言得屠者專諸也。坎為弓、為員、為忠，坎數五，巽顛隕，故曰伍氏夷誅，謂伍員也。《左傳》伍員進專諸於吳公子光，《吳越春秋》專諸曰：王何好，光曰：好魚炙，專諸乃去，從太湖學魚炙。○屠，汲古訛居，今依宋元本。</p><h3 id="漸之蹇" tabindex="-1">漸之蹇 <a class="header-anchor" href="#漸之蹇" aria-label="Permalink to “漸之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>敏捷亟疾，如猿集木。彤弓雖調，終不能獲。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>水流動故曰敏捷亟疾。艮為猿、為木，坎為集，故曰如猿集木。坎為弓、為赤，故曰彤弓。艮為終。</p><h3 id="漸之解" tabindex="-1">漸之解 <a class="header-anchor" href="#漸之解" aria-label="Permalink to “漸之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>冠帶南行，與福相期。邀於嘉國，拜位逢時。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《漸》象。位，汲古作為，音訛字，依宋本。行，宋元作遊，漸艮為冠，巽為帶。互離，故曰南行。震為福、為嘉，艮為國、為拜、為時。</p><h3 id="漸之損" tabindex="-1">漸之損 <a class="header-anchor" href="#漸之損" aria-label="Permalink to “漸之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>年豐歲熟，政仁民樂，祿入獲福。坤為年歲、為多，故曰豐熟。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為政、為民，震為仁、為樂、為福祿。</p><h3 id="漸之益" tabindex="-1">漸之益 <a class="header-anchor" href="#漸之益" aria-label="Permalink to “漸之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>築闕石顛，立基泉源。疾病不安，老孤無鄰。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《艮》之《復》。泉，汲古作水，依宋元本。</p><h3 id="漸之夬" tabindex="-1">漸之夬 <a class="header-anchor" href="#漸之夬" aria-label="Permalink to “漸之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>逐狐東山，水遏我前。深不可涉，失利後還。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《蠱》。</p><h3 id="漸之姤" tabindex="-1">漸之姤 <a class="header-anchor" href="#漸之姤" aria-label="Permalink to “漸之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>麟子鳳雛，生長嘉國。和氣所居，康樂溫仁，邦多聖人。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>伏坤為麟鳳，震為子、為雛、為生長。坤為國、為邦，震為樂、為仁，乾為聖人。</p><h3 id="漸之萃" tabindex="-1">漸之萃 <a class="header-anchor" href="#漸之萃" aria-label="Permalink to “漸之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>西行求玉，冀得瑜璞。反得兇惡，使我驚惑。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>兌為西，伏震為瑜璞、為玉，艮為求，故曰西行求玉。坤為兇惡、為憂惑。○瑜，汲古作卞，依宋元本。</p><h3 id="漸之升" tabindex="-1">漸之升 <a class="header-anchor" href="#漸之升" aria-label="Permalink to “漸之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>心狂老悖，視聽聾盲。正命無常，下民多孽。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為心、為老悖，易以兌為眇，二至四互兌，故曰視盲。初至四互大坎，故曰聽聾。巽為命，巽進退不果，故曰無常。坤為民、為孽、為下、為多。</p><h3 id="漸之困" tabindex="-1">漸之困 <a class="header-anchor" href="#漸之困" aria-label="Permalink to “漸之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>南國少子，材略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《漸》。此亦用漸象。</p><h3 id="漸之井" tabindex="-1">漸之井 <a class="header-anchor" href="#漸之井" aria-label="Permalink to “漸之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>逶迤高原，家伯妄施，亂其五官。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏艮為高原。伏震為伯，艮為家，故曰家伯。家伯，幽王臣助王為虐者也，《詩小雅》家伯冡宰是也。離為亂，艮為官，互坎，卦數五，故曰五官。</p><h3 id="漸之革" tabindex="-1">漸之革 <a class="header-anchor" href="#漸之革" aria-label="Permalink to “漸之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>謝恩拜德，東歸吾國，歡樂有福。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>震為恩德，艮為拜、為國，震為東、為反，故曰東歸吾國。震為樂、為福。全用旁通象。</p><h3 id="漸之鼎" tabindex="-1">漸之鼎 <a class="header-anchor" href="#漸之鼎" aria-label="Permalink to “漸之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>雞鳴同興，思配無家。執佩持鳧，無所致之。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>巽為雞、為鳴，伏震為興。艮為家，艮伏，故曰無家。艮為執持、為鳧，震為玉，故曰佩。坤虛，故曰無所致之。《詩鄭風》女曰雞鳴，士曰昧旦；將翔將翔，弋鳧與雁，又知子之來之，雜佩以贈之。○興，汲古訛舉，佩作佩，無所作莫使，茲均依宋元本。</p><h3 id="漸之震" tabindex="-1">漸之震 <a class="header-anchor" href="#漸之震" aria-label="Permalink to “漸之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>兇重憂累，身受誅罪，神不能解。坎為兇憂、為桎梏，艮為身，故曰身受誅罪。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為神、為解，坎陷，故不能解。○累，汲古作慮，依宋元本。</p><h3 id="漸之艮" tabindex="-1">漸之艮 <a class="header-anchor" href="#漸之艮" aria-label="Permalink to “漸之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>虎豹熊羆，遊戲山谷。仁賢君子，得其所欲。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《中孚》。</p><h3 id="漸之漸" tabindex="-1">漸之漸 <a class="header-anchor" href="#漸之漸" aria-label="Permalink to “漸之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>別離分散，長子從軍。稚叔就賊，寡老獨居，莫為種瓜。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>巽隕落，故別離分散。震為長子、為爭戰，震伏，故曰長子從軍。艮為少男，故曰身叔。艮坎連，故曰就賊。巽為寡，艮為老，坎為孤獨，故曰寡老獨居。艮為果蓏，故曰瓜。○居，汲古作安，非，依宋元本。</p><h3 id="漸之歸妹" tabindex="-1">漸之歸妹 <a class="header-anchor" href="#漸之歸妹" aria-label="Permalink to “漸之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>海隅遼右，福祿所至。柔嘉蒙佑，九夷何咎。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌為海、為右，震居東北，故曰遼右。震為福祿，數九，故曰九夷。坎為夷也。</p><h3 id="漸之豐" tabindex="-1">漸之豐 <a class="header-anchor" href="#漸之豐" aria-label="Permalink to “漸之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>華首之山，仙道所遊。利以居止，長無咎憂。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《井》。</p><h3 id="漸之旅" tabindex="-1">漸之旅 <a class="header-anchor" href="#漸之旅" aria-label="Permalink to “漸之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>甲乙戊庚，隨時轉行。不失常節，萌芽律屈。鹹達生出，各樂其類。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《坤》。樂，汲古作順。</p><h3 id="漸之巽" tabindex="-1">漸之巽 <a class="header-anchor" href="#漸之巽" aria-label="Permalink to “漸之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>跛躓未起，失利後市，不得鹿子。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏《震》。震為起，坎蹇，故跛躓。巽為利市，坎為失，震為後，故曰失利後市。震為鹿、為子，風散，故不得。</p><h3 id="漸之兌" tabindex="-1">漸之兌 <a class="header-anchor" href="#漸之兌" aria-label="Permalink to “漸之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>怙恃自負，不去於下。血從地出，誅罰失理。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏艮為負，二陽皆在上，故曰不去於下，言有所恃不肯居下也，《詩》曰無父何怙，無母何恃。坎為血，居重陰之間，故曰血從地出。坎為刑罰。</p><h3 id="漸之渙" tabindex="-1">漸之渙 <a class="header-anchor" href="#漸之渙" aria-label="Permalink to “漸之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>江河淮海，天之都市。商人受福，國家饒有。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《小畜》。</p><h3 id="漸之節" tabindex="-1">漸之節 <a class="header-anchor" href="#漸之節" aria-label="Permalink to “漸之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>節情省欲，賦斂有度。家給人足，且貴且富。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為情慾，艮止，故曰節、曰省。坎為聚，故曰賦斂。度，《說文》法制也。坎為法，故曰有度。艮為家，震為人，艮貴震富。○末句宋元本作利以富貴，依汲古。</p><h3 id="漸之中孚" tabindex="-1">漸之中孚 <a class="header-anchor" href="#漸之中孚" aria-label="Permalink to “漸之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>池鳴呴，呼求水潦。雲雨大會，流成河海。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為呴，兌為池，震為鳴呼。伏大坎為潦、為雲雨、為河海。○池，宋本、汲古作牝馬，元本作牝牛，依《隨》之《臨》校。呴，宋元本作哅，依汲古。水，各本皆作其，依《隨》之《臨》校。</p><h3 id="漸之小過" tabindex="-1">漸之小過 <a class="header-anchor" href="#漸之小過" aria-label="Permalink to “漸之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>日月之塗，所行必到，無有患故。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為日，兌為月，震為大塗、為行，震樂，故無有患故。</p><h3 id="漸之既濟" tabindex="-1">漸之既濟 <a class="header-anchor" href="#漸之既濟" aria-label="Permalink to “漸之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>乘風而舉，與飛鳥俱。一舉千里，見吾愛母。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《鼎》。</p><h3 id="漸之未濟" tabindex="-1">漸之未濟 <a class="header-anchor" href="#漸之未濟" aria-label="Permalink to “漸之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>陰配陽爭，臥木反立。君子攸行，喪其官職。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>卦三陽三陰，故曰陰配陽爭，言陰盛與陽爭也。昭帝元鳳三年春，上林有柳樹枯僵自起生，故曰臥木反立。時眭孟言僵柳復起，將有匹夫為天子者，被誅。三四句亦似指其事。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
